// Enforce single global initialization before crypto-dependent APIs.
// If already initialized, allow re-invocation to exercise idempotent paths safely.
int already = FUZZ_GET_ATTR_INT_GLOBAL("xmlsec_crypto_inited");
if (already) {
    // Re-initializing is not guaranteed to be safe in real life; bail to avoid UB.
    FUZZ_BAIL();
}
int ret = xmlSecCryptoInit();
// xmlsec convention: 0 == success, negative on error
if (ret != 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT_GLOBAL("xmlsec_crypto_inited", 1);
// Validation: ensure our global flag is set and observable by other stubs
FUZZ_ASSERT(FUZZ_GET_ATTR_INT_GLOBAL("xmlsec_crypto_inited") == 1, "crypto init flag must be set after xmlSecCryptoInit");
// Validation summary: Initializes backend once per session; sets a global attr to gate dependent calls.

// Must be called only after successful xmlSecCryptoInit().
int inited = FUZZ_GET_ATTR_INT_GLOBAL("xmlsec_crypto_inited");
if (!inited) { FUZZ_BAIL(); }
int ret = xmlSecCryptoShutdown();
if (ret != 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT_GLOBAL("xmlsec_crypto_inited", 0);
// Validation: ensure the flag is cleared so no crypto API is used post-shutdown
FUZZ_ASSERT(FUZZ_GET_ATTR_INT_GLOBAL("xmlsec_crypto_inited") == 0, "crypto init flag must be cleared after shutdown");
// Validation summary: Enforces init-before-shutdown and clears global state.

// Require crypto to be initialized prior to manager initialization.
if (!FUZZ_GET_ATTR_INT_GLOBAL("xmlsec_crypto_inited")) { FUZZ_BAIL(); }
// mngr is provided by the fuzzer runtime and must be non-null and allocated.
// Initialize default crypto-backed stores into the manager.
int ret = xmlSecCryptoKeysMngrInit(mngr);
if (ret < 0) { FUZZ_BAIL(); }
// Track that this manager has been initialized with crypto defaults.
FUZZ_SET_ATTR_INT(mngr, "crypto_mngr_inited", 1);
// Validation: attribute must reflect initialization status for downstream APIs.
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(mngr, "crypto_mngr_inited") == 1, "keys manager should be marked as initialized");
// Validation summary: Ensures crypto precondition, checks return code, and returns the mngr to the pool.

// Getter requires crypto backend initialized.
