import base64
import random
import textwrap
from typing import List

def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]

# Small library of plausible subject/issuer components. Not exhaustive, but valid-ish.
_CN = [
    "Example Root CA",
    "Intermediate CA",
    "Fuzzer Test CA",
    "Service Cert",
    "User Cert",
]
_O = ["Example Corp", "Acme Inc", "Contoso Ltd", "XmlSec Test", "OpenSSL Org"]
_C = ["US", "DE", "FR", "GB", "JP", "CN", "BR", "IN"]
_OU = ["IT", "Security", "Engineering", "QA", "Research"]

# Minimal ASN.1 DER generator for a very small, valid-looking X.509 TBSCertificate
# We are not implementing full RFC 5280; instead we build a consistently structured
# self-signed v3 certificate that most parsers will accept for load/parse operations.
# The goal is valid DER so xmlsec/OpenSSL can parse it.

# DER helpers

def _der_len(length: int) -> bytes:
    if length < 0x80:
        return bytes([length])
    b = []
    while length > 0:
        b.append(length & 0xFF)
        length >>= 8
    b.reverse()
    return bytes([0x80 | len(b)]) + bytes(b)


def _der_tlv(tag: int, content: bytes) -> bytes:
    return bytes([tag]) + _der_len(len(content)) + content

# Universal tags
_TAG_INTEGER = 0x02
_TAG_BIT_STRING = 0x03
_TAG_OCTET_STRING = 0x04
_TAG_NULL = 0x05
_TAG_OID = 0x06
_TAG_UTF8STRING = 0x0C
_TAG_SEQUENCE = 0x30
_TAG_SET = 0x31
_TAG_UTCTIME = 0x17
_TAG_GENERALIZEDTIME = 0x18

# Context-specific constructed [0], [1], ...
def _ctx_constructed(n: int, content: bytes) -> bytes:
    return _der_tlv(0xA0 + n, content)

# INTEGER encoder that supports small positive values

def _der_int(n: int) -> bytes:
    if n == 0:
        content = b"\x00"
    else:
        b = []
        x = n
        while x > 0:
            b.append(x & 0xFF)
            x >>= 8
        b.reverse()
        # If high bit set, prepend 0x00 to keep positive
        if b and (b[0] & 0x80):
            b = [0] + b
        content = bytes(b)
    return _der_tlv(_TAG_INTEGER, content)

# OID encoder from dotted string

def _der_oid(oid: str) -> bytes:
    parts = [int(x) for x in oid.split('.')]
    if len(parts) < 2:
        raise ValueError("bad oid")
    first = 40 * parts[0] + parts[1]
    body = [first]
    for p in parts[2:]:
        enc = []
        if p == 0:
            enc = [0]
        else:
            while p > 0:
                enc.append(0x80 | (p & 0x7F))
                p >>= 7
            enc[-1] &= 0x7F
            enc.reverse()
        body.extend(enc)
    return _der_tlv(_TAG_OID, bytes(body))

# Name (RDNSequence) builder: SEQUENCE of SET of SEQUENCE(oid, value)

def _der_rdn(oid: str, value_utf8: str) -> bytes:
    atv = _der_tlv(_TAG_SEQUENCE, _der_oid(oid) + _der_tlv(_TAG_UTF8STRING, value_utf8.encode('utf-8')))
    rdn = _der_tlv(_TAG_SET, atv)
    return rdn


def _der_name(common: str, org: str, country: str, ou: str) -> bytes:
    # Use common OIDs: CN (2.5.4.3), O (2.5.4.10), C (2.5.4.6), OU (2.5.4.11)
    rdns = []
    rdns.append(_der_rdn("2.5.4.3", common))
    rdns.append(_der_rdn("2.5.4.10", org))
    rdns.append(_der_rdn("2.5.4.6", country))
    rdns.append(_der_rdn("2.5.4.11", ou))
    return _der_tlv(_TAG_SEQUENCE, b"".join(rdns))

# Time encoders: keep them simple and valid. Use UTCTime for years < 2050, GeneralizedTime otherwise

def _der_time_utc(y, m, d, hh, mm, ss) -> bytes:
    # YYMMDDhhmmssZ
    yy = y % 100
    s = f"{yy:02d}{m:02d}{d:02d}{hh:02d}{mm:02d}{ss:02d}Z"
    return _der_tlv(_TAG_UTCTIME, s.encode('ascii'))


def _der_time_gen(y, m, d, hh, mm, ss) -> bytes:
    s = f"{y:04d}{m:02d}{d:02d}{hh:02d}{mm:02d}{ss:02d}Z"
    return _der_tlv(_TAG_GENERALIZEDTIME, s.encode('ascii'))


def _der_validity(not_before, not_after) -> bytes:
    def enc(t):
