    # basicConstraints OID: 2.5.29.19; SEQUENCE { cA BOOLEAN DEFAULT FALSE }
    bc = _der_tlv(_TAG_SEQUENCE, _der_boolean(is_ca))
    return _der_tlv(_TAG_SEQUENCE, _der_oid("2.5.29.19") + _der_tlv(_TAG_OCTET_STRING, bc))


def _ext_subject_key_identifier(keyid: bytes) -> bytes:
    # OID 2.5.29.14 OCTET STRING of keyid
    val = _der_tlv(_TAG_OCTET_STRING, keyid)
    return _der_tlv(_TAG_SEQUENCE, _der_oid("2.5.29.14") + _der_tlv(_TAG_OCTET_STRING, val))


def _build_extensions(rng: random.Random) -> bytes:
    exts = []
    is_ca = rng.choice([True, False])
    exts.append(_ext_basic_constraints(is_ca))
    keyid = bytes(rng.randrange(0, 256) for _ in range(rng.randrange(8, 20)))
    exts.append(_ext_subject_key_identifier(keyid))
    seq = _der_tlv(_TAG_SEQUENCE, b"".join(exts))
    # [3] EXPLICIT Extensions
    return _ctx_constructed(3, seq)

# SignatureAlgorithm: sha256WithRSAEncryption (1.2.840.113549.1.1.11)

def _sig_alg_sha256_rsa() -> bytes:
    return _der_tlv(_TAG_SEQUENCE, _der_oid("1.2.840.113549.1.1.11") + _der_tlv(_TAG_NULL, b""))

# Construct a self-signed certificate with matching subject/issuer and placeholder signature bits

def _build_der_cert(rng: random.Random) -> bytes:
    serial = rng.randint(1, 1 << 20)

    # Version v3: [0] EXPLICIT Version INTEGER(2)
    version = _ctx_constructed(0, _der_int(2))

    # Signature (in TBSCertificate) matches sig alg: sha256WithRSAEncryption
    tbs_sig_alg = _sig_alg_sha256_rsa()

    # Subject/Issuer names
    subj = _der_name(_rand_choice(rng, _CN), _rand_choice(rng, _O), _rand_choice(rng, _C), _rand_choice(rng, _OU))
    issuer = subj  # self-signed

    # Validity window: around current-ish synthetic times
    y = rng.randint(2015, 2035)
    nb = (y, rng.randint(1, 12), rng.randint(1, 28), rng.randint(0, 23), rng.randint(0, 59), rng.randint(0, 59))
    na = (min(y + rng.randint(1, 5), 2040), rng.randint(1, 12), rng.randint(1, 28), rng.randint(0, 23), rng.randint(0, 59), rng.randint(0, 59))
    validity = _der_validity(nb, na)

    spki = _build_rsa_spki(rng)

    extensions = _build_extensions(rng)

    tbs = _der_tlv(
        _TAG_SEQUENCE,
        version +
        _der_int(serial) +
        tbs_sig_alg +
        issuer +
        validity +
        subj +
        spki +
        extensions,
    )

    sig_alg = _sig_alg_sha256_rsa()

    # Make up a signature bit-string of appropriate size (512-bit RSA -> signature size 64 bytes)
    signature_bytes = bytes(rng.randrange(0, 256) for _ in range(64))
    signature = _der_bit_string_from_bytes(signature_bytes)

    cert = _der_tlv(_TAG_SEQUENCE, tbs + sig_alg + signature)
    return cert

# PEM encoder

def _to_pem(label: str, der: bytes, line: int = 64) -> bytes:
    b64 = base64.b64encode(der).decode('ascii')
    wrapped = "\n".join(textwrap.wrap(b64, width=line))
    s = f"-----BEGIN {label}-----\n{wrapped}\n-----END {label}-----\n"
    return s.encode('ascii')


def _maybe_make_pem(rng: random.Random, der: bytes) -> bytes:
    # Randomly choose PEM or raw DER; include variants to target different formats:
    choice = rng.random()
    if choice < 0.6:
        return _to_pem("CERTIFICATE", der, line=rng.choice([64, 76]))
    elif choice < 0.7:
        # Certificate plus trailing newline noise that parsers usually ignore
        pem = _to_pem("CERTIFICATE", der)
        return pem + b"\n"
    else:
        # Raw DER
        return der


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    der = _build_der_cert(rng)

    # Adjust size bounds to fit within fuzzers (<= 2048). Our DER is tiny; PEM will be ~1k.
    out = _maybe_make_pem(rng, der)
    if len(out) > 4096:
        # Should not happen, but truncate safely at certificate boundary by re-encoding with shorter base64 lines
        out = _to_pem("CERTIFICATE", der, line=64)
    return out
